package pa1.controller;

import pa1.model.Cell;
import pa1.model.Direction;
import pa1.model.EntityCell;
import pa1.model.ExtraLife;
import pa1.model.GameBoard;
import pa1.model.Gem;
import pa1.model.Mine;
import pa1.model.MoveResult;
import pa1.model.Position;
import pa1.model.StopCell;

import java.util.*;

/**
 * Controller for {@link GameBoard}.
 *
 * <p>
 * This class is responsible for providing high-level operations to mutate a {@link GameBoard}. This should be the only
 * class which mutates the game board; Other classes should use this class to mutate the game board.
 * </p>
 */
public class GameBoardController {

    private final GameBoard gameBoard;

    /**
     * Creates an instance.
     *
     * @param gameBoard The instance of {@link GameBoard} to control.
     */
    public GameBoardController(final GameBoard gameBoard) {
        this.gameBoard = gameBoard;
    }

    /**
     * Moves the player in the given direction.
     *
     * <p>
     * You should ensure that the game board is only mutated if the move is valid and results in the player still being
     * alive. If the player dies after moving or the move is invalid, the game board should remain in the same state as
     * before this method was called.
     * </p>
     *
     * @param direction Direction to move the player in.
     * @return An instance of {@link MoveResult} representing the result of this action.
     */
    public MoveResult makeMove(final Direction direction) {
        EntityCell currentCell = gameBoard.getPlayer().getOwner();
        Position currentPos = currentCell.getPosition();
        PositionOffset offset = direction.getOffset();
        Position newPos = currentPos.offsetByOrNull(offset, gameBoard.getNumRows(), gameBoard.getNumCols());

        if (newPos == null) {
            return new MoveResult.Invalid(currentPos);
        }

        Cell targetCell = gameBoard.getCell(newPos);
        if (!(targetCell instanceof EntityCell)) {
            return new MoveResult.Invalid(currentPos);
        }

        EntityCell targetEntityCell = (EntityCell) targetCell;
        Entity targetEntity = targetEntityCell.getEntity();

        // Handle different entity types
        if (targetEntity instanceof Mine) {
            return new MoveResult.Valid.Dead(newPos, newPos);
        } else if (targetEntity instanceof Gem || targetEntity instanceof ExtraLife) {
            // Collect gems and extra lives
            List<Position> collectedGems = new ArrayList<>();
            List<Position> collectedExtraLives = new ArrayList<>();

            if (targetEntity instanceof Gem) {
                collectedGems.add(newPos);
            } else if (targetEntity instanceof ExtraLife) {
                collectedExtraLives.add(newPos);
            }

            // Move player
            Player player = gameBoard.getPlayer();
            currentCell.setEntity(null);
            targetEntityCell.setEntity(player);

            return new MoveResult.Valid.Alive(newPos, currentPos, collectedGems, collectedExtraLives);
        } else if (targetEntity == null) {
            // Move to empty cell
            Player player = gameBoard.getPlayer();
            currentCell.setEntity(null);
            targetEntityCell.setEntity(player);

            return new MoveResult.Valid.Alive(newPos, currentPos, Collections.emptyList(), Collections.emptyList());
        } else {
            return new MoveResult.Invalid(currentPos);
        }
    }

    /**
     * Undoes a move by reverting all changes performed by the specified move.
     *
     * <p>
     * Hint: Undoing a move is effectively the same as reversing everything you have done to make a move.
     * </p>
     *
     * @param prevMove The {@link MoveResult} object to revert.
     */
    public void undoMove(final MoveResult prevMove) {
        if (prevMove instanceof MoveResult.Valid) {
            MoveResult.Valid validMove = (MoveResult.Valid) prevMove;
            Position newPos = validMove.newPosition;
            Position origPos = validMove.origPosition;

            EntityCell newCell = gameBoard.getEntityCell(newPos);
            EntityCell origCell = gameBoard.getEntityCell(origPos);
            Player player = gameBoard.getPlayer();

            // Move player back
            newCell.setEntity(null);
            origCell.setEntity(player);

            // Restore collected items if any
            if (validMove instanceof MoveResult.Valid.Alive) {
                MoveResult.Valid.Alive aliveMove = (MoveResult.Valid.Alive) validMove;

                // Restore gems
                for (Position gemPos : aliveMove.collectedGems) {
                    EntityCell cell = gameBoard.getEntityCell(gemPos);
                    cell.setEntity(new Gem());
                }

                // Restore extra lives
                for (Position lifePos : aliveMove.collectedExtraLives) {
                    EntityCell cell = gameBoard.getEntityCell(lifePos);
                    cell.setEntity(new ExtraLife());
                }
            }
        }
        // No action needed for invalid or dead moves
    }
}
```

### Key Implementation Details:

1. **Constructor**: Simply stores the provided game board reference.

2. **makeMove()**:
   - Gets the player's current position and calculates the new position based on the direction
   - Checks if the move is valid (within bounds and to an EntityCell)
   - Handles different entity types:
     - Mines result in a Dead move result
     - Gems and ExtraLives are collected and result in Alive move results
     - Empty cells result in simple movement
   - Only updates the game board state for valid moves that keep the player alive

3. **undoMove()**:
   - For valid moves, moves the player back to the original position
   - For Alive moves with collected items, restores the gems and extra lives to their original positions
   - Doesn't need to handle Dead or Invalid moves since they don't change the board state

The implementation ensures that:
- The game board state remains consistent
- Only valid moves that keep the player alive actually modify the board
- Undo operations perfectly reverse the changes made by moves
- All edge cases (out of bounds, invalid cells) are handled properly

