package pa1.controller;

import pa1.model.Direction;
import pa1.model.GameState;
import pa1.model.MoveResult;
import pa1.model.Position;

import java.util.*;

/**
 * Controller for {@link pa1.InertiaTextGame}.
 *
 * <p>
 * All game state mutations should be performed by this class.
 * </p>
 */
public class GameController {

    private final GameState gameState;

    /**
     * Creates an instance.
     *
     * @param gameState The instance of {@link GameState} to control.
     */
    public GameController(final GameState gameState) {
        this.gameState = gameState;
    }

    /**
     * Processes a Move action performed by the player.
     *
     * @param direction The direction the player wants to move to.
     * @return An instance of {@link MoveResult} indicating the result of the action.
     */
    public MoveResult processMove(final Direction direction) {
        if (gameState.hasWon() || gameState.hasLost()) {
            return new MoveResult.Invalid(gameState.getGameBoard().getPlayerPosition());
        }

        MoveResult result = gameState.getGameBoardController().makeMove(direction);
        gameState.incrementNumMoves();

        if (result instanceof MoveResult.Valid) {
            gameState.getMoveStack().push(result);

            if (result instanceof MoveResult.Valid.Alive aliveResult) {
                // Handle gem collection
                if (!aliveResult.collectedGems.isEmpty()) {
                    gameState.getGameBoard().removeGems(aliveResult.collectedGems);
                }
                // Handle extra lives collection
                if (!aliveResult.collectedExtraLives.isEmpty()) {
                    gameState.getGameBoard().removeExtraLives(aliveResult.collectedExtraLives);
                    gameState.increaseNumLives(aliveResult.collectedExtraLives.size());
                }
            } else if (result instanceof MoveResult.Valid.Dead deadResult) {
                gameState.incrementNumDeaths();
                gameState.decrementNumLives();
            }
        }

        return result;
    }

    /**
     * Processes an Undo action performed by the player.
     *
     * @return {@code false} if there are no steps to undo.
     */
    public boolean processUndo() {
        if (gameState.getMoveStack().isEmpty() || gameState.hasWon() || gameState.hasLost()) {
            return false;
        }

        MoveResult lastMove = gameState.getMoveStack().pop();
        gameState.getGameBoardController().undoMove(lastMove);
        gameState.incrementNumMoves(); // Count undo as a move

        if (lastMove instanceof MoveResult.Valid.Alive aliveResult) {
            // Return gems if any were collected
            if (!aliveResult.collectedGems.isEmpty()) {
                gameState.getGameBoard().addGems(aliveResult.collectedGems);
            }
            // Return extra lives if any were collected
            if (!aliveResult.collectedExtraLives.isEmpty()) {
                gameState.getGameBoard().addExtraLives(aliveResult.collectedExtraLives);
                gameState.decreaseNumLives(aliveResult.collectedExtraLives.size());
            }
        } else if (lastMove instanceof MoveResult.Valid.Dead) {
            // Reverse death count and lives
            gameState.increaseNumLives(1);
            gameState.decreaseNumLives(1); // net zero change for undo of death
        }

        return true;
    }
}
```

