 * Controller for {@link pa1.InertiaTextGame}.
 *
 * <p>
 * All game state mutations should be performed by this class.
 * </p>
 */
public class GameController {

    private final GameState gameState;

    /**
     * Creates an instance.
     *
     * @param gameState The instance of {@link GameState} to control.
     */
    public GameController(final GameState gameState) {
        this.gameState = gameState;
    }

    /**
     * Processes a Move action performed by the player.
     *
     * @param direction The direction the player wants to move to.
     * @return An instance of {@link MoveResult} indicating the result of the action.
     */
    public MoveResult processMove(final Direction direction) {
        GameBoardController boardController = gameState.getGameBoardController();
        MoveResult result = boardController.makeMove(direction);

        if (result instanceof MoveResult.Valid) {
            gameState.incrementNumMoves();

            if (result instanceof MoveResult.Valid.Alive) {
                MoveResult.Valid.Alive aliveResult = (MoveResult.Valid.Alive) result;
                // Update gems collected
                for (Position gemPos : aliveResult.collectedGems) {
                    gameState.getGameBoard().removeGem(gemPos);
                }
                // Update extra lives collected
                for (Position lifePos : aliveResult.collectedExtraLives) {
                    gameState.getGameBoard().removeExtraLife(lifePos);
                    gameState.increaseNumLives(1);
                }
                gameState.getMoveStack().push(result);

            } else if (result instanceof MoveResult.Valid.Dead) {
                MoveResult.Valid.Dead deadResult = (MoveResult.Valid.Dead) result;
                gameState.incrementNumDeaths();
                if (!gameState.hasUnlimitedLives()) {
                    gameState.decrementNumLives();
                }
                gameState.getMoveStack().push(result);
            }
        }

        return result;
    }

    /**
     * Processes an Undo action performed by the player.
     *
     * @return {@code false} if there are no steps to undo.
     */
    public boolean processUndo() {
        if (gameState.getMoveStack().isEmpty()) {
            return false;
        }

        MoveResult lastMove = gameState.getMoveStack().pop();
        gameState.getGameBoardController().undoMove(lastMove);

        if (lastMove instanceof MoveResult.Valid) {
            gameState.incrementNumMoves(); // Count undo as a move

            if (lastMove instanceof MoveResult.Valid.Alive) {
                MoveResult.Valid.Alive aliveResult = (MoveResult.Valid.Alive) lastMove;
                // Restore gems
                for (Position gemPos : aliveResult.collectedGems) {
                    gameState.getGameBoard().addGem(gemPos);
                }
                // Restore extra lives
                for (Position lifePos : aliveResult.collectedExtraLives) {
                    gameState.getGameBoard().addExtraLife(lifePos);
                    gameState.decreaseNumLives(1);
                }

            } else if (lastMove instanceof MoveResult.Valid.Dead) {
                MoveResult.Valid.Dead deadResult = (MoveResult.Valid.Dead) lastMove;
                gameState.decrementNumDeaths();
                if (!gameState.hasUnlimitedLives()) {
                    gameState.increaseNumLives(1);
                }
            }
        }

        return true;
    }
}
```

This implementation:

1. **Constructor**: Initializes the GameController with the provided GameState.

2. **processMove**:
   - Gets the GameBoardController from GameState
   - Makes the move in the specified direction
   - Handles different MoveResult cases:
     - For Valid.Alive moves: updates gem/extra life counts and pushes to move stack
     - For Valid.Dead moves: updates death/life counts and pushes to move stack
   - Returns the MoveResult

3. **processUndo**:
   - Checks if there are moves to undo
   - Pops the last move from the stack
   - Undoes the move using GameBoardController
   - Handles different MoveResult cases to restore game state:
     - For Valid.Alive: restores gems and extra lives
     - For Valid.Dead: restores death/life counts
   - Returns true if undo was successful, false if no moves to undo

The implementation follows the principle that all game state mutations should go through the controller, and properly handles all the different move result cases while maintaining game state consistency.

