     *                                  </ul>
     */
    public GameBoard(final int numRows, final int numCols, final Cell[][] cells) {
        if (numRows != cells.length || numCols != cells[0].length) {
            throw new IllegalArgumentException("Board dimensions don't match cell array dimensions");
        }

        this.numRows = numRows;
        this.numCols = numCols;
        this.board = new Cell[numRows][numCols];

        // Copy cells and count players/gems
        int playerCount = 0;
        int gemCount = 0;
        Player tempPlayer = null;

        for (int i = 0; i < numRows; i++) {
            for (int j = 0; j < numCols; j++) {
                board[i][j] = cells[i][j];
                if (cells[i][j] instanceof EntityCell) {
                    Entity entity = ((EntityCell) cells[i][j]).getEntity();
                    if (entity instanceof Player) {
                        playerCount++;
                        tempPlayer = (Player) entity;
                    } else if (entity instanceof Gem) {
                        gemCount++;
                    }
                }
            }
        }

        if (playerCount != 1) {
            throw new IllegalArgumentException("There must be exactly one player on the board");
        }
        if (gemCount == 0) {
            throw new IllegalArgumentException("There must be at least one gem on the board");
        }

